def kmeans_centers(points, n_clusters):
    if not points:
        raise ValueError("points must not be empty")
    if n_clusters <= 0:
        raise ValueError("n_clusters must be positive")
    if n_clusters > len(points):
        raise ValueError("n_clusters cannot exceed the number of points")

    data = [[float(x), float(y)] for x, y in points]
    k = n_clusters
    n = len(data)

    if k == 1:
        cx = sum(p[0] for p in data) / n
        cy = sum(p[1] for p in data) / n
        return [[cx, cy]]

    if k == n:
        return sorted(([x, y] for x, y in data), key=lambda p: (p[0], p[1]))

    # Deterministic farthest-first initialization.
    centroids = [data[0][:]]
    chosen = {0}

    for _ in range(1, k):
        best_idx = None
        best_dist = -1.0

        for i, p in enumerate(data):
            if i in chosen:
                continue

            min_dist = min(
                (p[0] - c[0]) ** 2 + (p[1] - c[1]) ** 2
                for c in centroids
            )

            if min_dist > best_dist:
                best_dist = min_dist
                best_idx = i

        chosen.add(best_idx)
        centroids.append(data[best_idx][:])

    assignments = [-1] * n

    for _ in range(300):
        new_assignments = []

        for p in data:
            best_cluster = 0
            best_dist = float("inf")

            for j, c in enumerate(centroids):
                dist = (p[0] - c[0]) ** 2 + (p[1] - c[1]) ** 2
                if dist < best_dist:
                    best_dist = dist
                    best_cluster = j

            new_assignments.append(best_cluster)

        sums = [[0.0, 0.0] for _ in range(k)]
        counts = [0] * k

        for i, cluster in enumerate(new_assignments):
            sums[cluster][0] += data[i][0]
            sums[cluster][1] += data[i][1]
            counts[cluster] += 1

        new_centroids = []
        max_shift_sq = 0.0

        for j in range(k):
            if counts[j] > 0:
                c = [sums[j][0] / counts[j], sums[j][1] / counts[j]]
            else:
                c = centroids[j][:]

            dx = c[0] - centroids[j][0]
            dy = c[1] - centroids[j][1]
            max_shift_sq = max(max_shift_sq, dx * dx + dy * dy)

            new_centroids.append(c)

        converged = (
            new_assignments == assignments
            and max_shift_sq <= 1e-24
        )

        centroids = new_centroids
        assignments = new_assignments

        if converged:
            break

    result = [[float(c[0]), float(c[1])] for c in centroids]
    result.sort(key=lambda p: (p[0], p[1]))
    return result
