def fit_linear_regression(features, values):
    values = [float(v) for v in values]

    if not features:
        return {"coefficients": [], "intercept": 0.0}

    features = [[float(x) for x in row] for row in features]
    n = len(features[0])
    p = n + 1

    # Normal equations: (X^T X) beta = X^T y,
    # with an intercept column appended as the last column of X.
    A = [[0.0 for _ in range(p)] for _ in range(p)]
    b = [0.0 for _ in range(p)]

    for row, y in zip(features, values):
        x = row + [1.0]
        for i in range(p):
            b[i] += x[i] * y
            for j in range(p):
                A[i][j] += x[i] * x[j]

    # Gaussian elimination with partial pivoting.
    for col in range(p):
        pivot = max(range(col, p), key=lambda r: abs(A[r][col]))

        if abs(A[pivot][col]) < 1e-12:
            continue

        if pivot != col:
            A[col], A[pivot] = A[pivot], A[col]
            b[col], b[pivot] = b[pivot], b[col]

        for r in range(col + 1, p):
            factor = A[r][col] / A[col][col]
            if abs(factor) < 1e-15:
                continue

            for c in range(col, p):
                A[r][c] -= factor * A[col][c]
            b[r] -= factor * b[col]

    # Back substitution.
    beta = [0.0] * p
    for i in range(p - 1, -1, -1):
        total = b[i]
        for j in range(i + 1, p):
            total -= A[i][j] * beta[j]

        if abs(A[i][i]) > 1e-12:
            beta[i] = total / A[i][i]
        else:
            beta[i] = 0.0

    return {
        "coefficients": [float(v) for v in beta[:-1]],
        "intercept": float(beta[-1]),
    }
