import math

def letter_count_correlations(strings):
    if not strings:
        return None

    letters = sorted({ch for s in strings for ch in s})
    if not letters:
        return {}

    n = len(strings)

    # Count each letter in each string
    counts = {
        letter: [s.count(letter) for s in strings]
        for letter in letters
    }

    # Center the count vectors
    means = {letter: sum(values) / n for letter, values in counts.items()}
    centered = {
        letter: [value - means[letter] for value in values]
        for letter, values in counts.items()
    }

    # Norms used in the Pearson correlation denominator
    norms = {
        letter: math.sqrt(sum(x * x for x in values))
        for letter, values in centered.items()
    }

    result = {}

    for x in letters:
        result[x] = {}
        for y in letters:
            if x == y:
                result[x][y] = 1.0
            else:
                covariance = sum(
                    xv * yv for xv, yv in zip(centered[x], centered[y])
                )
                result[x][y] = covariance / (norms[x] * norms[y])

    return result
