import csv
import io
import re
from datetime import datetime

def _validate_date(date_str):
    if not isinstance(date_str, str) or re.fullmatch(r"\d{4}-\d{2}-\d{2}", date_str) is None:
        raise ValueError(f"Invalid date: {date_str!r}")
    try:
        datetime.strptime(date_str, "%Y-%m-%d")
    except ValueError:
        raise ValueError(f"Invalid date: {date_str!r}") from None
    return date_str

def filter_rows_by_date_range(csv_text, column_name, start_date, end_date):
    start_date = _validate_date(start_date)
    end_date = _validate_date(end_date)

    reader = csv.reader(io.StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError(f"Column {column_name!r} not found") from None

    try:
        col_idx = header.index(column_name)
    except ValueError:
        raise ValueError(f"Column {column_name!r} not found") from None

    result = []
    for row in reader:
        if col_idx >= len(row):
            continue

        value = row[col_idx]

        # YYYY-MM-DD strings can be compared lexicographically.
        if start_date <= value <= end_date:
            result.append(row)

    return result
