from html.parser import HTMLParser


class _DataTableParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.rows = []
        self.found = False
        self.done = False
        self.table_depth = 0
        self.target_depth = None
        self.current_row = None
        self.cell_parts = None

    def _finish_cell(self):
        if self.cell_parts is not None:
            if self.current_row is not None:
                self.current_row.append("".join(self.cell_parts))
            self.cell_parts = None

    def _finish_row(self):
        self._finish_cell()
        if self.current_row is not None:
            self.rows.append(self.current_row)
            self.current_row = None

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()

        if tag == "table":
            self.table_depth += 1

            if not self.found and not self.done:
                class_value = None
                for name, value in attrs:
                    if name.lower() == "class":
                        class_value = value
                        break

                if class_value == "data-table":
                    self.found = True
                    self.target_depth = self.table_depth
            return

        if not self.found or self.done:
            return

        if tag == "tr":
            if self.table_depth == self.target_depth:
                if self.current_row is not None:
                    self._finish_row()
                self.current_row = []

        elif tag == "td":
            if self.table_depth == self.target_depth and self.current_row is not None:
                if self.cell_parts is not None:
                    self._finish_cell()
                self.cell_parts = []

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        self.handle_endtag(tag)

    def handle_endtag(self, tag):
        tag = tag.lower()

        if tag == "table":
            if self.found and not self.done and self.table_depth == self.target_depth:
                self._finish_row()
                self.done = True

            if self.table_depth > 0:
                self.table_depth -= 1
            return

        if not self.found or self.done:
            return

        if tag == "tr":
            if self.table_depth == self.target_depth and self.current_row is not None:
                self._finish_row()

        elif tag == "td":
            if self.table_depth == self.target_depth and self.cell_parts is not None:
                self._finish_cell()

    def handle_data(self, data):
        if self.found and not self.done and self.cell_parts is not None:
            self.cell_parts.append(data)


def extract_data_table_rows(html):
    parser = _DataTableParser()
    parser.feed(html)
    parser.close()

    if parser.found and not parser.done:
        parser._finish_row()

    return parser.rows
