import math

def merge_and_standardize(rows1, rows2):
    # Collect all feature columns, preserving first-seen order.
    first_cols = []
    for row in rows1:
        for key in row:
            if key != "id" and key not in first_cols:
                first_cols.append(key)

    second_cols = []
    for row in rows2:
        for key in row:
            if key != "id" and key not in second_cols:
                second_cols.append(key)

    # Compute population mean and standard deviation for table 1 columns.
    stats = {}
    for col in first_cols:
        values = [
            row[col]
            for row in rows1
            if col in row and row[col] is not None
        ]

        if not values:
            stats[col] = (None, None)
        else:
            mean = sum(values) / len(values)
            variance = sum((x - mean) ** 2 for x in values) / len(values)
            std = math.sqrt(variance)
            stats[col] = (mean, std)

    first_by_id = {row["id"]: row for row in rows1}
    second_by_id = {row["id"]: row for row in rows2}

    result = []

    for row_id in sorted(set(first_by_id) | set(second_by_id)):
        merged = {"id": row_id}

        first_row = first_by_id.get(row_id)
        for col in first_cols:
            value = first_row.get(col) if first_row is not None else None

            if value is None:
                merged[col] = None
            else:
                mean, std = stats[col]
                if std is None:
                    merged[col] = None
                elif std == 0:
                    merged[col] = 0.0
                else:
                    merged[col] = (value - mean) / std

        second_row = second_by_id.get(row_id)
        for col in second_cols:
            merged[col] = second_row.get(col) if second_row is not None else None

        result.append(merged)

    return result
