def seasonal_decomposition(values, period, model):
    n = len(values)
    p = int(period)

    if p <= 0:
        raise ValueError("period must be positive")
    if model not in ("additive", "multiplicative"):
        raise ValueError("model must be 'additive' or 'multiplicative'")
    if n < 2 * p:
        raise ValueError("series must contain at least two complete periods")

    trend = [None] * n
    half = p // 2

    # Centered moving average
    if p % 2 == 1:
        for i in range(half, n - half):
            trend[i] = sum(values[i - half:i + half + 1]) / p
    else:
        for i in range(half, n - half):
            weighted_sum = 0.5 * values[i - half]
            weighted_sum += sum(values[i - half + 1:i + half])
            weighted_sum += 0.5 * values[i + half]
            trend[i] = weighted_sum / p

    # Average detrended values by seasonal position
    sums = [0.0] * p
    counts = [0] * p

    for i, t in enumerate(trend):
        if t is not None:
            if model == "additive":
                detrended = values[i] - t
            else:
                detrended = values[i] / t

            phase = i % p
            sums[phase] += detrended
            counts[phase] += 1

    raw_seasonal = [
        sums[j] / counts[j] if counts[j] else 0.0
        for j in range(p)
    ]

    # Normalize seasonal indices
    if model == "additive":
        mean_seasonal = sum(raw_seasonal) / p
        seasonal_phase = [s - mean_seasonal for s in raw_seasonal]
    else:
        mean_seasonal = sum(raw_seasonal) / p
        seasonal_phase = [s / mean_seasonal for s in raw_seasonal]

    seasonal = [seasonal_phase[i % p] for i in range(n)]

    # Residual component
    residual = [None] * n

    for i, t in enumerate(trend):
        if t is not None:
            if model == "additive":
                residual[i] = values[i] - t - seasonal[i]
            else:
                residual[i] = values[i] / (t * seasonal[i])

    return {
        "trend": trend,
        "seasonal": seasonal,
        "residual": residual,
    }
