import math

def column_correlations(data):
    columns = list(data)
    n = len(next(iter(data.values()))) if data else 0

    means = {
        col: (sum(data[col]) / n if n else float("nan"))
        for col in columns
    }

    def pearson(x, y):
        xs, ys = data[x], data[y]
        mx, my = means[x], means[y]

        covariance = sum((a - mx) * (b - my) for a, b in zip(xs, ys))
        variance_x = sum((a - mx) ** 2 for a in xs)
        variance_y = sum((b - my) ** 2 for b in ys)

        denominator = math.sqrt(variance_x * variance_y)

        if denominator == 0:
            return float("nan")

        return covariance / denominator

    return {
        x: {y: pearson(x, y) for y in columns}
        for x in columns
    }
