from xml.etree import ElementTree as ET

def xml_to_dict(xml):
    try:
        root = ET.fromstring(xml)
    except ET.ParseError as e:
        raise ValueError(f"Malformed XML: {e}") from e

    def direct_text(elem):
        parts = []
        if elem.text:
            parts.append(elem.text)
        for child in elem:
            if child.tail:
                parts.append(child.tail)

        text = "".join(parts).strip()
        return text or None

    def convert(elem):
        children = list(elem)

        # Leaf element: no attributes and no children.
        if not elem.attrib and not children:
            text = elem.text.strip() if elem.text is not None else ""
            return text or None

        result = {}

        for name, value in elem.attrib.items():
            result["@" + name] = value

        for child in children:
            key = child.tag
            value = convert(child)

            if key in result:
                if isinstance(result[key], list):
                    result[key].append(value)
                else:
                    result[key] = [result[key], value]
            else:
                result[key] = value

        text = direct_text(elem)
        if text is not None:
            result["#text"] = text

        return result

    return {root.tag: convert(root)}
