import math
from numbers import Real


def row_averages_and_correlations(data):
    if not isinstance(data, list):
        raise ValueError("data must be a rectangular list of rows of numbers")

    n_rows = len(data)
    n_cols = None

    for row in data:
        if not isinstance(row, list):
            raise ValueError("each row must be a list of numbers")

        if n_cols is None:
            n_cols = len(row)
        elif len(row) != n_cols:
            raise ValueError("data must be rectangular")

        for value in row:
            if isinstance(value, bool) or not isinstance(value, Real):
                raise ValueError("all entries must be numbers")

    if n_rows == 0:
        return [], []

    if n_cols == 0:
        raise ValueError("rows must contain at least one number")

    averages = [sum(row) / n_cols for row in data]

    columns = [
        [data[row][col] for row in range(n_rows)]
        for col in range(n_cols)
    ]

    column_means = [sum(column) / n_rows for column in columns]

    deviations = []
    variances = []

    for col in range(n_cols):
        dev = [value - column_means[col] for value in columns[col]]
        deviations.append(dev)
        variances.append(sum(value * value for value in dev))

    corr = []
    for i in range(n_cols):
        corr_row = []
        for j in range(n_cols):
            if i == j:
                corr_row.append(1.0)
            else:
                denominator = math.sqrt(variances[i] * variances[j])
                if denominator == 0.0:
                    corr_row.append(0.0)
                else:
                    covariance = sum(
                        deviations[i][k] * deviations[j][k]
                        for k in range(n_rows)
                    )
                    corr_row.append(covariance / denominator)
        corr.append(corr_row)

    return averages, corr
