import math

def summarize_stock_column(column, data):
    column_indices = {
        'Open': 1,
        'High': 2,
        'Low': 3,
        'Close': 4,
        'Volume': 5
    }

    if column not in column_indices:
        raise ValueError(f"Invalid column name: {column}")

    idx = column_indices[column]
    values = []

    for row in data:
        if len(row) != 6:
            raise ValueError("Each row must contain exactly six entries")
        value = row[idx]
        if value is not None:
            values.append(float(value))

    values.sort()
    n = len(values)

    if n == 0:
        return {
            'count': 0,
            'mean': None,
            'std': None,
            'min': None,
            '25%': None,
            '50%': None,
            '75%': None,
            'max': None
        }

    mean = sum(values) / n

    if n > 1:
        std = math.sqrt(sum((x - mean) ** 2 for x in values) / (n - 1))
    else:
        std = 0.0

    def quantile(p):
        position = (n - 1) * p
        lower = math.floor(position)
        upper = math.ceil(position)

        if lower == upper:
            return float(values[lower])

        weight = position - lower
        return float(values[lower] * (1 - weight) + values[upper] * weight)

    return {
        'count': n,
        'mean': float(mean),
        'std': float(std),
        'min': float(values[0]),
        '25%': quantile(0.25),
        '50%': quantile(0.50),
        '75%': quantile(0.75),
        'max': float(values[-1])
    }
