            tokens = re.findall(r"\w{2,}", content.lower())
            picked_token_lists.append(tokens)

    n = len(picked_token_lists)
    if n == 0:
        return {}

    df = Counter()
    for tokens in picked_token_lists:
        df.update(set(tokens))

    scores = {}

    for tokens in picked_token_lists:
        tf = Counter(tokens)
        weights = {}
        norm_sq = 0.0

        for word, count in tf.items():
            idf = math.log((1 + n) / (1 + df[word])) + 1.0
            weight = count * idf
            weights[word] = weight
            norm_sq += weight * weight

        if norm_sq == 0:
            continue

        norm = math.sqrt(norm_sq)
        for word, weight in weights.items():
            scores[word] = scores.get(word, 0.0) + weight / norm

    return scores
