def grade_report(students, subjects, grades):
    report = {}
    n_students = len(students)
    n_subjects = len(subjects)

    subject_totals = {subject: 0.0 for subject in subjects}
    average_grade_total = 0.0

    for student, row in zip(students, grades):
        student_report = {}
        row_total = 0.0

        for subject, grade in zip(subjects, row):
            grade = float(grade)
            student_report[subject] = grade
            subject_totals[subject] += grade
            row_total += grade

        student_average = row_total / n_subjects if n_subjects else 0.0
        student_report['Average Grade'] = student_average
        average_grade_total += student_average

        report[student] = student_report

    averages = {
        subject: (subject_totals[subject] / n_students if n_students else 0.0)
        for subject in subjects
    }
    averages['Average Grade'] = (
        average_grade_total / n_students if n_students else 0.0
    )

    report['Average'] = averages
    return report
