from math import sqrt


def replace_and_standardize(data, features, mapping):
    for feature in features:
        if feature not in data:
            raise ValueError(f"Missing feature column: {feature!r}")

    # Replace mapped values throughout every column, preserving column order.
    result = {}
    for column, values in data.items():
        result[column] = [
            mapping[value] if value in mapping else value
            for value in values
        ]

    # Standardize each requested feature using population standard deviation.
    for feature in features:
        values = result[feature]
        n = len(values)

        if n == 0:
            continue

        mean = sum(values) / n
        variance = sum((x - mean) ** 2 for x in values) / n
        std = sqrt(variance)

        if std == 0:
            result[feature] = [0.0 for _ in values]
        else:
            result[feature] = [(x - mean) / std for x in values]

    return result
