from math import floor

def column_histogram(records, column_name):
    if not records:
        raise ValueError(f"Column {column_name!r} does not exist")

    values = []
    for row in records:
        if column_name not in row:
            raise ValueError(f"Column {column_name!r} does not exist")
        values.append(row[column_name])

    # Convert strings to indices based on sorted distinct string values.
    if values and all(isinstance(v, str) for v in values):
        distinct = sorted(set(values))
        mapping = {value: i for i, value in enumerate(distinct)}
        values = [mapping[value] for value in values]

    minimum = min(values)
    maximum = max(values)
    counts = [0] * 10

    if minimum == maximum:
        counts[9] = len(values)
        return counts

    width = (maximum - minimum) / 10

    for value in values:
        if value == maximum:
            index = 9
        else:
            index = floor((value - minimum) / width)
            index = max(0, min(index, 9))

        counts[index] += 1

    return counts
