import xml.etree.ElementTree as ET

def xml_to_dict(s):
    if s is None or not s.strip():
        raise ValueError("XML input must not be empty")

    root = ET.fromstring(s)

    def convert(elem):
        children = list(elem)

        # Text directly contained in this element:
        # its own text plus tails after child elements.
        text_parts = []
        if elem.text is not None:
            text_parts.append(elem.text)
        for child in children:
            if child.tail is not None:
                text_parts.append(child.tail)
        text = "".join(text_parts)

        # Empty element or element with only whitespace
        if not elem.attrib and not children:
            if text.strip() == "":
                return None
            return text

        result = {}

        for key, value in elem.attrib.items():
            result["@" + key] = value

        for child in children:
            tag = child.tag
            value = convert(child)

            if tag not in result:
                result[tag] = value
            else:
                if isinstance(result[tag], list):
                    result[tag].append(value)
                else:
                    result[tag] = [result[tag], value]

        if text.strip() != "":
            result["#text"] = text

        return result

    return {root.tag: convert(root)}
