from html.parser import HTMLParser


class _TableRecordsParser(HTMLParser):
    def __init__(self, table_id):
        super().__init__(convert_charrefs=True)
        self.table_id = table_id
        self.found = False
        self.in_target_table = False
        self.table_depth = 0  # nested tables inside the target table
        self.rows = []
        self.current_row = None
        self.in_cell = False
        self.cell_parts = []

    def _finish_cell(self):
        if self.in_cell:
            text = "".join(self.cell_parts).strip()
            if self.current_row is not None:
                self.current_row.append(text)
            self.in_cell = False
            self.cell_parts = []

    def _finish_row(self):
        self._finish_cell()
        if self.current_row is not None:
            self.rows.append(self.current_row)
            self.current_row = None

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()

        if tag == "table":
            if not self.found and dict(attrs).get("id") == self.table_id:
                self.found = True
                self.in_target_table = True
                self.table_depth = 0
            elif self.in_target_table:
                self.table_depth += 1
            return

        if not self.in_target_table or self.table_depth > 0:
            return

        if tag == "tr":
            self._finish_row()
            self.current_row = []
        elif tag in ("td", "th"):
            self._finish_cell()
            if self.current_row is None:
                self.current_row = []
            self.in_cell = True
            self.cell_parts = []

    def handle_endtag(self, tag):
        tag = tag.lower()

        if tag == "table":
            if self.in_target_table:
                if self.table_depth > 0:
                    self.table_depth -= 1
                else:
                    self._finish_row()
                    self.in_target_table = False
            return

        if not self.in_target_table or self.table_depth > 0:
            return

        if tag in ("td", "th"):
            self._finish_cell()
        elif tag == "tr":
            self._finish_row()

    def handle_data(self, data):
        if self.in_target_table and self.in_cell:
            self.cell_parts.append(data)

    def finish(self):
        if self.in_target_table:
            self._finish_row()
            self.in_target_table = False


def html_table_records(html, table_id):
    parser = _TableRecordsParser(table_id)
    parser.feed(html)
    parser.close()
    parser.finish()

    if not parser.found:
        raise ValueError(f"No table with id {table_id!r}")

    if not parser.rows:
        return []

    headers = parser.rows[0]
    return [dict(zip(headers, row)) for row in parser.rows[1:]]
