import csv
import io


def _is_numeric(value):
    if value is None:
        return False
    text = value.strip()
    if not text:
        return False
    try:
        float(text)
        return True
    except ValueError:
        return False


def _to_number(value):
    text = value.strip()
    try:
        return int(text)
    except ValueError:
        return float(text)


def sort_csv_rows(csv_text, sort_key):
    reader = csv.DictReader(io.StringIO(csv_text))

    if reader.fieldnames is None or sort_key not in reader.fieldnames:
        raise ValueError(f"Column {sort_key!r} does not exist")

    rows = list(reader)
    if not rows:
        return []

    fieldnames = reader.fieldnames

    numeric_columns = set()
    for field in fieldnames:
        if all(_is_numeric(row[field]) for row in rows):
            numeric_columns.add(field)

    converted_rows = []
    for row in rows:
        converted = {}
        for field in fieldnames:
            value = row[field]
            if field in numeric_columns:
                converted[field] = _to_number(value)
            else:
                converted[field] = value
        converted_rows.append(converted)

    converted_rows.sort(key=lambda row: row[sort_key])
    return converted_rows
