    if min_val == max_val:
        counts = [0] * bins
        counts[-1] = len(values)
        edges = [float(min_val)] * (bins + 1)
        return counts, edges

    width = (max_val - min_val) / bins
    edges = [float(min_val + i * width) for i in range(bins + 1)]
    edges[-1] = float(max_val)

    counts = [0] * bins
    for value in values:
        if value == max_val:
            index = bins - 1
        else:
            index = int((value - min_val) / width)
            if index < 0:
                index = 0
            elif index >= bins:
                index = bins - 1
        counts[index] += 1

    return counts, edges
