def attribute_histogram(records, key, num_bins=30):
    if num_bins <= 0:
        raise ValueError("num_bins must be positive")

    values = [record[key] for record in records]
    if not values:
        raise ValueError("records must contain at least one value")

    min_val = min(values)
    max_val = max(values)

    if min_val == max_val:
        edges = [float(min_val)] * (num_bins + 1)
        counts = [0] * num_bins
        counts[-1] = len(values)
        return counts, edges

    span = float(max_val) - float(min_val)
    edges = [
        float(min_val) + span * i / num_bins
        for i in range(num_bins + 1)
    ]
    edges[0] = float(min_val)
    edges[-1] = float(max_val)

    counts = [0] * num_bins

    for value in values:
        if value == max_val:
            idx = num_bins - 1
        else:
            idx = int((float(value) - float(min_val)) * num_bins / span)
            if idx < 0:
                idx = 0
            elif idx >= num_bins:
                idx = num_bins - 1

        counts[idx] += 1

    return counts, edges
