import math
from numbers import Real

def standardize_and_correlate(table):
    if not table:
        raise ValueError("table is empty")

    columns = list(table.keys())

    numeric_cols = []
    for col in columns:
        values = table[col]
        if values and all(
            isinstance(v, Real) and not isinstance(v, bool)
            for v in values
        ):
            numeric_cols.append(col)

    if not numeric_cols:
        raise ValueError("no numeric columns")

    n = len(table[columns[0]])

    standardized = {col: list(table[col]) for col in columns}
    means = {}
    stds = {}

    for col in numeric_cols:
        values = table[col]
        mean = sum(values) / n
        variance = sum((v - mean) ** 2 for v in values) / n
        std = math.sqrt(variance) if variance > 0 else 0.0

        means[col] = mean
        stds[col] = std

        if std == 0:
            standardized[col] = [0.0 for _ in values]
        else:
            standardized[col] = [(v - mean) / std for v in values]

    m = len(numeric_cols)
    corr = [[0.0] * m for _ in range(m)]

    for i, ci in enumerate(numeric_cols):
        for j, cj in enumerate(numeric_cols):
            if i == j:
                corr[i][j] = 1.0
            else:
                si = stds[ci]
                sj = stds[cj]

                if si == 0 or sj == 0:
                    corr[i][j] = 0.0
                else:
                    mi = means[ci]
                    mj = means[cj]
                    xi = table[ci]
                    xj = table[cj]

                    covariance = sum(
                        (a - mi) * (b - mj)
                        for a, b in zip(xi, xj)
                    ) / n

                    corr[i][j] = covariance / (si * sj)

    return standardized, corr
```

