from html.parser import HTMLParser


def extract_table_rows(html):
    class TableParser(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=True)
            self.rows = []
            self.row_stack = []
            self.cell_stack = []

        def handle_starttag(self, tag, attrs):
            if tag == "tr":
                row = []
                self.rows.append(row)
                self.row_stack.append(row)

            elif tag == "td":
                if self.row_stack:
                    cell = []
                    self.row_stack[-1].append(cell)
                    self.cell_stack.append(cell)

            # <th> cells are ignored as output cells.

        def handle_data(self, data):
            # Append text to every currently open <td>. This also preserves
            # text content correctly if tables are nested inside cells.
            for cell in self.cell_stack:
                cell.append(data)

        def handle_endtag(self, tag):
            if tag == "tr":
                if self.row_stack:
                    self.row_stack.pop()

            elif tag == "td":
                if self.cell_stack:
                    self.cell_stack.pop()

    parser = TableParser()
    parser.feed(html)
    parser.close()

    return [
        ["".join(cell).strip() for cell in row]
        for row in parser.rows
    ]
```

